"""Original neuromuscular-junction chapter, diagnostic and conventional MG care."""
from qbank_authoring import question,ref,finalize
MG=ref('International Consensus Guidance for MG, 2020 Update','https://pmc.ncbi.nlm.nih.gov/articles/PMC7884987/')
SY=ref('Guideline for Management of Myasthenic Syndromes, 2023','https://pmc.ncbi.nlm.nih.gov/articles/PMC10752078/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('Fluctuating diplopia and ptosis worsen with sustained upgaze and improve after rest. Pupils and sensation are normal. Which diagnosis is most likely?', 'Myasthenia gravis',[
 ('A fixed third-nerve palsy with pupil involvement','The fluctuating fatigable pattern and normal pupils favor a junctional disorder.'),('A sensory polyneuropathy','This does not explain selective fatigable ocular weakness.'),('Typical botulism as the best fit','Botulism more often adds autonomic and pupillary abnormalities with acute descending paralysis.')],
 'Fatigability is a physiological clue', '**MG causes impaired postsynaptic neuromuscular transmission.**', ['Ocular, bulbar, limb and respiratory muscles can be involved.','Normal pupils are an important distinction from some other acute ocular syndromes.'], '**Confirm rather than relying on one symptom.**', ['Use antibody testing and appropriate electrophysiology.','Assess bulbar and respiratory symptoms at presentation.'], [['Weakness','Fluctuating/fatigable'],['Pupils/sensation','Usually preserved'],['Localization','Postsynaptic junction']], [SY], 'clinical_scenario')
q('Which examination pattern is most typical of uncomplicated generalized MG?', 'Fatigable weakness with preserved sensation and usually preserved tendon reflexes',[
 ('Dense sensory loss with absent reflexes as a requirement','This favors a peripheral neuropathy.'),('Spasticity and extensor plantar responses as defining signs','These localize to upper motor neuron pathways.'),('Fixed dilated pupils as the cardinal sign','Pupil involvement is atypical for ordinary MG.')],
 'Identify the motor transmission syndrome', '**MG does not directly injure sensory pathways or the reflex arc in the usual way.**', ['Weakness can vary by task and time.','A normal examination between episodes does not fully exclude disease.'], '**Investigate unexpected signs.**', ['Coexisting disease can modify the examination.','Do not force marked sensory or upper motor neuron findings into an MG explanation.'], [['Sensation','Preserved'],['Reflexes','Usually preserved'],['Motor performance','Fatigable']], [SY])
q('What is the principal target of the commonest autoantibody subtype in generalized MG?', 'Postsynaptic acetylcholine receptor',[
 ('Presynaptic P/Q-type calcium channel','This is characteristic of LEMS.'),('Aquaporin-4','This is associated with NMOSD.'),('Peripheral myelin protein 22','This is relevant to inherited neuropathies.')],
 'The antigen identifies a disease mechanism', '**AChR antibodies reduce the effective safety margin of neuromuscular transmission.**', ['Complement injury, receptor loss and functional effects contribute.','The endplate architecture can become simplified.'], '**Use antibody subtype in treatment planning.**', ['Thymic associations and targeted therapy eligibility differ.','Negative AChR testing does not exclude all MG.'], [['AChR MG','Postsynaptic receptor'],['LEMS','Presynaptic calcium channel'],['Testing','Subtype informs management']], [SY,MG])
q('Prominent bulbar and neck weakness occurs in an AChR-antibody-negative patient. MuSK antibodies are detected. Which statement is most appropriate?', 'This is an MG subtype with distinct treatment considerations, often including early consideration of rituximab when initial therapy is inadequate',[
 ('MuSK positivity establishes a presynaptic calcium-channel disorder','MuSK is part of postsynaptic endplate organization.'),('Thymectomy is routinely indicated solely because MuSK is positive','Evidence does not support routine nonthymomatous thymectomy for this subtype.'),('Pyridostigmine must work equally well in every MG subtype','Benefit and tolerability can differ in MuSK disease.')],
 'MuSK disease is not simply antibody-negative AChR MG', '**MuSK antibodies often involve IgG4-mediated disruption of endplate organization.**', ['Bulbar and respiratory involvement can be substantial.','Cholinesterase inhibitors may be less effective or poorly tolerated.'], '**Choose subtype-informed therapy.**', ['Rituximab has a particular role in refractory or inadequately controlled MuSK MG.','Assess swallowing and breathing carefully.'], [['Target','MuSK endplate signaling'],['Clinical clue','Bulbar/neck predominance'],['Treatment','Subtype-specific decisions']], [MG,SY], 'clinical_scenario')
q('AChR and MuSK antibody tests are negative despite a convincing fatigable syndrome. What is the best next principle?', 'Pursue appropriate electrophysiology and specialist evaluation; seronegativity does not exclude all MG',[
 ('MG is excluded with certainty','Antibody sensitivity varies, especially in ocular disease.'),('Diagnose MG from symptoms alone without checking mimics','Objective confirmation and differential diagnosis remain important.'),('Assume all seronegative cases need thymectomy','That decision cannot be made from seronegativity alone.')],
 'A negative assay narrows rather than ends the evaluation', '**Some MG patients lack antibodies detected by routine tests.**', ['Specialized assays or additional targets may help selected cases.','Congenital syndromes and other mimics deserve consideration.'], '**Seek objective transmission evidence.**', ['Test clinically involved muscles where appropriate.','Interpret physiology within the phenotype.'], [['Routine antibodies','Not universally positive'],['Electrophysiology','Adds objective evidence'],['Mimics','Must remain under review']], [SY])
q('What low-frequency repetitive nerve-stimulation pattern supports a postsynaptic transmission disorder?', 'A reproducible qualifying decrement in compound muscle response',[
 ('A purely sensory response reduction as the defining finding','This evaluates a different component of the peripheral system.'),('Uniformly slow sensory conduction alone','This suggests a neuropathic rather than junctional process.'),('A large brief-exercise increment as the most typical MG pattern','That is more characteristic of presynaptic failure such as LEMS.')],
 'Repeated activation exposes a reduced safety margin', '**Low-frequency RNS can demonstrate decrement in MG.**', ['Sensitivity depends on muscle selection and disease distribution.','Technical factors can create misleading changes.'], '**Do not use a negative distal study to exclude ocular disease.**', ['Facial or proximal testing may improve yield.','Single-fiber studies can be considered when needed.'], [['MG','Low-frequency decrement'],['LEMS','Postexercise increment'],['Technique','Reproducibility matters']], [SY])
q('Single-fiber EMG shows increased jitter. What is the most accurate interpretation?', 'It supports impaired neuromuscular transmission but is not uniquely specific for autoimmune MG',[
 ('It identifies the AChR antibody subtype directly','The test does not measure the antigen-specific antibody.'),('It excludes all neuropathic or myopathic contributions','Jitter can increase in other motor-unit disorders.'),('It proves thymoma','Thymic imaging is a separate assessment.')],
 'A sensitive physiological test has specificity limits', '**Jitter measures variability in transmission timing.**', ['Blocking can occur when transmission fails.','Muscle selection and technical expertise matter.'], '**Combine the result with the clinical syndrome.**', ['A compatible examination and antibody pattern improve interpretation.','Avoid diagnosis from jitter alone.'], [['Jitter','Timing variability'],['Blocking','Transmission failure'],['Specificity','Not unique to MG']], [SY])
q('An ice-pack test transiently improves ptosis. What does this result mean?', 'It supports ocular MG in the appropriate context but does not replace a full diagnostic assessment',[
 ('It definitively proves every form of generalized MG','The test is supportive rather than a complete diagnostic pathway.'),('It proves a fixed third-nerve lesion','The reversible response favors a different mechanism.'),('A negative result excludes MG permanently','Sensitivity and technique are imperfect.')],
 'A bedside response is one piece of evidence', '**Cooling can improve myasthenic ptosis transiently.**', ['Document the lid position objectively.','The test does not assess all ocular and generalized manifestations equally.'], '**Confirm and assess severity.**', ['Use antibodies and physiology as indicated.','Ask about bulbar and respiratory symptoms despite an ocular presentation.'], [['Positive response','Supportive'],['Negative response','Not absolute exclusion'],['Next step','Complete syndrome assessment']], [SY])
q('What imaging assessment is important after diagnosing autoimmune MG?', 'Chest imaging to assess for thymoma',[
 ('A brain amyloid PET scan in every case','This does not evaluate the relevant thymic association.'),('No imaging because thymic pathology is impossible','Thymoma is an important association.'),('Only plain wrist radiographs','These do not address the clinical question.')],
 'A neurological syndrome can reveal a mediastinal tumor', '**CT or suitable MRI of the mediastinum evaluates thymic pathology.**', ['Thymoma changes the surgical and oncological plan.','Thymic hyperplasia is a different finding.'], '**Coordinate surgery after appropriate stabilization.**', ['Bulbar and respiratory status affect perioperative risk.','A thymoma indication differs from elective thymectomy for nonthymomatous disease.'], [['Imaging target','Thymus'],['Thymoma','Oncological implications'],['Timing','Neurological stabilization']], [MG,SY])
q('What is the main action of pyridostigmine in MG?', 'Inhibit acetylcholinesterase to prolong acetylcholine availability at the endplate',[
 ('Deplete CD20-positive B cells','That is the mechanism of selected immune therapies.'),('Block presynaptic potassium channels','This is the amifampridine mechanism.'),('Remove the thymoma directly','Surgical or oncological treatment is separate.')],
 'Symptomatic therapy increases transmission opportunity', '**Pyridostigmine improves transmission without directly eliminating the autoimmune cause.**', ['Benefit varies with phenotype.','Muscarinic adverse effects include diarrhea, cramping and secretions.'], '**Adjust to useful function and tolerability.**', ['Excess dosing can cause adverse cholinergic effects.','Inadequate control may require immunotherapy.'], [['Action','Acetylcholinesterase inhibition'],['Benefit','Symptomatic'],['Limitation','Does not remove autoimmunity']], [SY])
q('Generalized MG remains functionally limiting despite pyridostigmine. Which principle is appropriate?', 'Add suitable immunotherapy rather than relying indefinitely on symptomatic-dose escalation alone',[
 ('Pyridostigmine escalation is the only possible treatment','Immune therapies are central in persistent disease.'),('Avoid all immune therapy because symptoms fluctuate','Fluctuation does not imply harmless disease.'),('Use a sedative as the primary disease-modifying strategy','Sedation does not treat the autoimmune process.')],
 'Treat the underlying immune disease when needed', '**Corticosteroids and steroid-sparing agents are conventional options.**', ['Choice depends on severity, subtype and comorbidity.','Newer targeted treatments have specific indications.'], '**Plan treatment onset and monitoring.**', ['Some drugs take months to provide full benefit.','Use bridging strategies when rapid control is needed.'], [['Pyridostigmine','Symptomatic control'],['Immunotherapy','Underlying disease control'],['Monitoring','Efficacy and toxicity']], [MG,SY], 'clinical_scenario')
q('Why may a patient with severe bulbar MG need close monitoring when high-dose corticosteroids are initiated?', 'Transient early worsening can occur before immune benefit develops',[
 ('Steroids inevitably cure weakness within minutes','The benefit is not immediate.'),('Steroids have no role in MG','They are an important treatment despite initiation risks.'),('Bulbar weakness never affects airway safety','Aspiration and respiratory compromise are major concerns.')],
 'Treatment initiation can have an early risk phase', '**Steroid-associated early worsening is important in vulnerable patients.**', ['Severity and the planned regimen influence monitoring needs.','IVIG or exchange may be used as rapid therapy or a bridge.'], '**Choose the setting according to risk.**', ['Assess swallowing, cough and ventilation.','Avoid unsupervised high-risk initiation.'], [['Early phase','Possible worsening'],['Later phase','Immune benefit'],['High-risk patient','Monitored specialist plan']], [MG,SY], 'clinical_scenario')
q('Why is azathioprine not used as the sole immediate rescue for myasthenic crisis?', 'Its immunosuppressive benefit is delayed rather than an immediate restoration of transmission',[
 ('It is a direct rapid acetylcholinesterase inhibitor','That describes a different drug class.'),('It invariably worsens every MG subtype','It is used as a steroid-sparing treatment in selected patients.'),('It removes all need for blood and liver monitoring','Toxicity monitoring is necessary.')],
 'Long-term control and acute rescue have different time courses', '**Azathioprine is a maintenance steroid-sparing option with delayed benefit.**', ['Monitor blood counts and liver effects.','Pretreatment pharmacogenetic or enzyme assessment follows local protocols.'], '**Use rapid therapy for unstable disease.**', ['Crisis management requires respiratory support and IVIG or exchange.','Continue a coordinated long-term plan after stabilization.'], [['Azathioprine','Delayed maintenance effect'],['IVIG/exchange','Rapid immune treatment'],['Airway support','Immediate life-saving care']], [MG,SY])
q('Which nonthymomatous MG group has the strongest established evidence supporting elective thymectomy?', 'Selected adults with generalized AChR-antibody-positive MG, particularly early in the disease',[
 ('Every MuSK-positive patient regardless of phenotype','Routine nonthymomatous thymectomy is not established for MuSK disease.'),('Every transient neonatal MG case','Passive maternal antibodies cause that syndrome.'),('All patients with isolated sensory complaints','That does not establish MG.')],
 'The thymectomy evidence is subtype- and population-specific', '**Consensus supports considering early thymectomy in suitable generalized AChR-positive adults.**', ['The pivotal trial population and individual age and duration matter.','Expected benefit is reduction of disease and treatment burden over time.'], '**Separate thymoma surgery from this elective indication.**', ['Thymoma has its own oncological rationale.','Operate when the patient is sufficiently stable.'], [['AChR generalized MG','Established elective evidence'],['MuSK MG','No routine equivalent indication'],['Thymoma','Separate oncological decision']], [MG])
q('An MG patient has worsening dysphagia, weak cough and respiratory weakness. Which diagnosis requires urgent consideration?', 'Impending or established myasthenic crisis',[
 ('An uncomplicated ocular fluctuation','Bulbar and respiratory findings indicate higher risk.'),('A reason to wait for antibody titers before assessing ventilation','Titers do not determine immediate airway safety.'),('A harmless effect if oxygen saturation remains normal','Ventilatory reserve can fail before saturation declines.')],
 'Crisis is a respiratory and airway emergency', '**Bulbar dysfunction can impair secretion handling and increase aspiration risk.**', ['Serial respiratory measures and trajectory are important.','A normal saturation does not prove adequate reserve.'], '**Escalate to an experienced monitored setting.**', ['Treat triggers and consider rapid immune therapy.','Plan elective airway support when needed.'], [['Bulbar weakness','Aspiration/secretions'],['Respiratory weakness','Ventilation risk'],['Action','Urgent monitored assessment']], [MG,SY], 'clinical_scenario')
q('Which rapid immune treatments are used in significant myasthenic exacerbation or crisis?', 'Plasma exchange or IVIG, selected according to clinical circumstances',[
 ('Azathioprine alone as minute-to-minute rescue','Its benefit is delayed.'),('Elective thymectomy before stabilizing the airway','Acute stabilization takes priority.'),('Repeated sedative doses as disease treatment','Sedation can aggravate respiratory compromise.')],
 'Rapid immune control complements respiratory support', '**Exchange and IVIG are established short-term strategies.**', ['Exchange may act rapidly and is often favored in selected severe or MuSK cases.','Access, hemodynamics, thrombosis and renal factors influence choice.'], '**Treat the precipitant and plan maintenance.**', ['Infection and drug exposures are common triggers.','Do not mistake transient rescue benefit for a complete long-term plan.'], [['Exchange','Rapid antibody removal'],['IVIG','Immune modulation'],['Support','Airway and trigger management']], [MG,SY])

